'use strict';
const KEY='launchtrack.applications.v1';
const statuses=['Applied','Interview','Offer','Rejected'];
const $=s=>document.querySelector(s);let applications=[],filter='All',storageAvailable=true;
try{const data=JSON.parse(localStorage.getItem(KEY)||'[]');if(Array.isArray(data))applications=data.filter(a=>a&&typeof a.id==='string'&&typeof a.company==='string'&&typeof a.role==='string'&&statuses.includes(a.status)&&/^\d{4}-\d{2}-\d{2}$/.test(a.date));}catch{storageAvailable=false;}
function toast(message){$('#toast').textContent=message;$('#toast').style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').style.display='none',3500);}
function save(){try{localStorage.setItem(KEY,JSON.stringify(applications));storageAvailable=true;}catch{storageAvailable=false;toast('Storage unavailable. Export CSV to keep a backup.');}$('.local').textContent=storageAvailable?'● Saved on this device':'● Changes kept in memory only';render();}
function el(tag,text,cls){const n=document.createElement(tag);n.textContent=text;if(cls)n.className=cls;return n;}
function render(){const counts=Object.fromEntries(statuses.map(s=>[s,applications.filter(a=>a.status===s).length]));$('.stats').replaceChildren();[['Total applications',applications.length,'Your search so far'],['In progress',counts.Applied,'Applications submitted'],['Interviews',counts.Interview,'Conversations ahead'],['Offers',counts.Offer,'New possibilities']].forEach(([title,count,note],i)=>{const card=el('article','','stat'),top=el('div',title);top.append(el('span',['↗','◷','◉','✓'][i],'icon'));card.append(top,el('b',count),el('small',note));$('.stats').append(card);});$('#count').textContent=applications.length;$('#tabs').replaceChildren();['All',...statuses].forEach(s=>{const b=el('button',s,s===filter?'selected':'');b.setAttribute('aria-pressed',s===filter);b.onclick=()=>{filter=s;render();};$('#tabs').append(b);});const q=$('#search').value.toLowerCase().trim();const visible=applications.filter(a=>(filter==='All'||a.status===filter)&&`${a.company} ${a.role} ${a.location||''}`.toLowerCase().includes(q)).sort((a,b)=>b.date.localeCompare(a.date));$('tbody').replaceChildren();for(const a of visible){const tr=document.createElement('tr'),company=document.createElement('td'),wrap=el('div','','company'),avatar=el('span',a.company.slice(0,2).toUpperCase(),'avatar'),info=document.createElement('div');info.append(el('strong',a.company),el('small',a.role));wrap.append(avatar,info);company.append(wrap);const status=document.createElement('td');status.append(el('span',a.status,'badge '+a.status));const actions=el('div','','row-actions');const edit=el('button','Edit');edit.onclick=()=>openForm(a);edit.setAttribute('aria-label',`Edit ${a.company} application`);const del=el('button','Delete');del.setAttribute('aria-label',`Delete ${a.company} application`);del.onclick=()=>{if(confirm(`Delete the ${a.company} application?`)){applications=applications.filter(x=>x.id!==a.id);save();toast('Application deleted');}};actions.append(edit,del);const td=document.createElement('td');td.append(actions);tr.append(company,status,el('td',a.location||'—'),el('td',new Date(a.date+'T00:00:00').toLocaleDateString('en-IN',{day:'numeric',month:'short',year:'numeric'})),td);$('tbody').append(tr);}$('#empty').hidden=visible.length>0;$('#shown').textContent=`Showing ${visible.length} of ${applications.length} applications`;}
function openForm(a){$('#form').reset();$('#form-title').textContent=a?'Edit application':'Add application';const defaults=a||{id:'',date:new Date().toLocaleDateString('en-CA'),status:'Applied'};for(const [k,v]of Object.entries(defaults)){const input=$('#form').elements.namedItem(k);if(input)input.value=v||'';}if(!a)$('#form').elements.date.value=new Date().getFullYear()+'-'+String(new Date().getMonth()+1).padStart(2,'0')+'-'+String(new Date().getDate()).padStart(2,'0');$('dialog').showModal();}
$('#add').onclick=()=>openForm();$('#close').onclick=$('#cancel').onclick=()=>$('dialog').close();$('#search').oninput=render;$('#form').onsubmit=e=>{e.preventDefault();const data=Object.fromEntries(new FormData(e.target));data.company=data.company.trim();data.role=data.role.trim();if(!data.company||!data.role){toast('Enter a company and job title.');return;}const editing=Boolean(data.id);data.id=data.id||(crypto.randomUUID?crypto.randomUUID():Date.now().toString(36)+'-'+Math.random().toString(36).slice(2));applications=applications.filter(a=>a.id!==data.id);applications.push(data);save();$('dialog').close();toast(editing?'Application updated':'Application added');};
$('#export').onclick=()=>{if(!applications.length){toast('Add an application before exporting.');return;}const columns=['company','role','status','location','date','notes'];const escape=value=>'"'+String(value??'').replace(/^[=+@\-\t\r]/,"'$&").replaceAll('"','""')+'"';const csv=[columns.join(','),...applications.map(a=>columns.map(k=>escape(a[k])).join(','))].join('\r\n');const url=URL.createObjectURL(new Blob(['\uFEFF'+csv],{type:'text/csv;charset=utf-8;'}));const link=document.createElement('a');link.href=url;link.download='launchtrack-applications.csv';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Applications exported');};render();if(!storageAvailable){$('.local').textContent='● Storage unavailable';toast('Browser storage unavailable. Export CSV to keep a backup.');}
